<div id="toast" class="pointer-events-none fixed bottom-6 left-1/2 z-50 -translate-x-1/2 translate-y-4 rounded-xl bg-[#2b1406] px-5 py-3 text-sm font-semibold text-white opacity-0 shadow-xl transition">Added to bag!</div>
<script>
const toast=document.getElementById('toast');let timer;
function showToast(text){toast.textContent=text;toast.classList.remove('opacity-0','translate-y-4');toast.classList.add('opacity-100','translate-y-0');clearTimeout(timer);timer=setTimeout(()=>{toast.classList.add('opacity-0','translate-y-4');toast.classList.remove('opacity-100','translate-y-0')},2400)}
document.querySelectorAll('.filter-btn').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filter-btn').forEach(b=>b.className='filter-btn rounded-full bg-[#f4e6d7] px-4 py-2 text-sm font-semibold text-[#2b1406]');btn.className='filter-btn rounded-full bg-[#2b1406] px-4 py-2 text-sm font-semibold text-white';const f=btn.dataset.filter;document.querySelectorAll('.product-card').forEach(c=>c.classList.toggle('hidden',f!=='all'&&c.dataset.category!==f))}));
document.querySelectorAll('.product-card').forEach(card=>{let qty=1;const count=card.querySelector('.qty-count');card.querySelector('.qty-minus').onclick=()=>{qty=Math.max(1,qty-1);count.textContent=qty};card.querySelector('.qty-plus').onclick=()=>{qty=Math.min(20,qty+1);count.textContent=qty};card.querySelector('.add-to-cart').onclick=()=>showToast(`Added ${qty}x ${card.querySelector('h2').textContent} to bag!`)});document.querySelector('.add-bundle').onclick=()=>showToast('The Duo Gift Box added to bag!');
</script>
<script>
async function addCartItem(product, quantity) { const response = await fetch('{{ route('cart.add') }}', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content, 'Accept': 'application/json' }, body: JSON.stringify({ product, quantity }) }); const data = await response.json(); if (response.ok) showToast(`${data.message} (${data.count} items)`); }
document.querySelectorAll('.add-to-cart').forEach((button, index) => button.addEventListener('click', () => { const card = button.closest('.product-card'); addCartItem(index === 0 ? 'classic' : 'dark', Number(card.querySelector('.qty-count').textContent)); }));
document.querySelector('.add-bundle').addEventListener('click', () => addCartItem('duo', 1));
</script>
